                "    (repo_dir / 'app.txt').write_text('hello\\n')\n"
                "    git_run(['add', '.'], repo_dir)\n"
                "    git_run(['-c', 'commit.gpgsign=false', 'commit', '-qm', 'init'], repo_dir)\n"
                "    git_run(['remote', 'add', 'origin', str(origin_dir)], repo_dir)\n"
